dynamicFvMesh   adaptiveFvMesh;
errorEstimator  densityGradient;

// When can unrefinement start
beginUnrefine 1e-5;

// How often to refine
refineInterval  3;

// Refine field in between lower..upper
lowerRefineLevel 0.1;

// If value < unrefineLevel unrefine
unrefineLevel   0.1;

// Have slower than 2:1 refinement
nBufferLayers   3;

// Refine cells only up to maxRefinement levels
maxRefinement   3;

// Write the refinement level as a volScalarField
dumpLevel       true;

laminarFlameSpeedCorrelation RaviPetersen;

fuel            HydrogenInAir;

Su              Su [0 1 -1 0 0 0 0] 0.434;

SuModel         unstrained;

equivalenceRatio equivalenceRatio [0 0 0 0 0 0 0] 1;

sigmaExt        sigmaExt [0 0 -1 0 0 0 0] 100000;

dimensions      [0 1 -1 0 0 0 0];

internalField   uniform 0.434;

boundaryField
{
    walls
    {
        type            zeroGradient;
    }
    defaultFaces
    {
        type            empty;
    }
}

activationModel programmedIgnition;
initiation
{
    // Detonation energy
    E0              4.0e9;

    // Detonation points
    points
    (
        (0 0.02 0)
        (0 0.1 0)
        (0 0.2 0)
        (0 0.3 0)
        (0 0.4 0)
        (0 0.5 0)
    );

    // Delays
    delays
    (
        0.0
        5e-6
        10e-6
        5e-6
        10e-6
        0.0
    );

    // Radii to set (for each point)
    radius 0.01; // Radius of activation (overridden by radii entry)
    radii
    (
        0   // use the closest cell
        0.02
        0.03
        0.015
        0.025
        0.01
    );

    // Detonation velocity
    vDet    7850;

    // Chapman-Jouguet pressure
    Pcj     0.1017e11;

    // Linear and compression activation
    burnModel programmedBeta;

    pMin 1.1e5;
}

pressureProbes
{
    type           blastProbes;
    writeControl   timeStep;
    writeInterval  1;
    adjustLocations yes;

    probeLocations
    (
        (1 0 0)
        (2 0 0)
        (5 0 0)
        (10 0 0)
        (15 0 0)
        (20 0 0)
    );
    fields
    (
        p
        impulse
        dynamicP
    );
}

